      out.write("<script>\r\n");
      out.write("	// 하트 토글 통신 함수\r\n");
      out.write("	function toggleWish(event, sIdx, btn) {\r\n");
      out.write("	    event.preventDefault();\r\n");
      out.write("	    event.stopPropagation(); // 카드 링크로 이동하는 것을 방지하고 하트만 토글시킴\r\n");
      out.write("	    \r\n");
      out.write("	    fetch('/api/wish/toggle', {\r\n");
      out.write("	        method: 'POST',\r\n");
      out.write("	        headers: { 'Content-Type': 'application/json' },\r\n");
      out.write("	        body: JSON.stringify({ sIdx: sIdx })\r\n");
      out.write("	    })\r\n");
      out.write("	    .then(response => {\r\n");
      out.write("	        if (response.status === 401) {\r\n");
      out.write("	            if (window.LoginRequiredPrompt) { window.LoginRequiredPrompt.open(); } else { if (window.LoginRequiredPrompt) { window.LoginRequiredPrompt.open(); } else { alert('로그인이 필요한 서비스입니다.'); } }\r\n");
      out.write("	            return;\r\n");
      out.write("	        }\r\n");
      out.write("	        return response.json();\r\n");
      out.write("	    })\r\n");
      out.write("	    .then(data => {\r\n");
      out.write("	        if (data && data.success) {\r\n");
      out.write("	            btn.innerText = data.isHearted ? '❤️' : '🤍';\r\n");
      out.write("	            if (data.isHearted) btn.classList.add('active');\r\n");
      out.write("	            else btn.classList.remove('active');\r\n");
      out.write("	        }\r\n");
      out.write("	    })\r\n");
      out.write("	    .catch(error => {\r\n");
      out.write("	        console.error('Error:', error);\r\n");
      out.write("	        alert('처리 중 오류가 발생했습니다.');\r\n");
      out.write("	    });\r\n");
      out.write("	}\r\n");
      out.write("	\r\n");
      out.write("	// =========================================================\r\n");
      out.write("		// ✅ 전체보기(all.jsp) 사이드바 카테고리 클릭 시 깜빡임 없이 부드러운 화면 전환\r\n");
      out.write("		// =========================================================\r\n");
      out.write("		document.addEventListener(\"DOMContentLoaded\", function() {\r\n");
      out.write("		    const menuLinks = document.querySelectorAll('.menu-item a');\r\n");
      out.write("		    const contentArea = document.querySelector('.content-area');\r\n");
      out.write("\r\n");
      out.write("		    menuLinks.forEach(link => {\r\n");
      out.write("		        link.addEventListener('click', function(e) {\r\n");
      out.write("		            e.preventDefault(); // 기본 새로고침 멈춤\r\n");
      out.write("		            const url = this.href;\r\n");
      out.write("\r\n");
      out.write("		            // 1. 사이드바 활성화 버튼 색상 즉시 변경\r\n");
      out.write("		            document.querySelectorAll('.menu-item').forEach(li => li.classList.remove('active'));\r\n");
      out.write("		            this.closest('.menu-item').classList.add('active');\r\n");
      out.write("\r\n");
      out.write("		            // 2. 오른쪽 카드 영역을 스르륵 투명하게 만들기 (Fade-out)\r\n");
      out.write("		            contentArea.style.transition = \"opacity 0.2s ease-in-out\";\r\n");
      out.write("		            contentArea.style.opacity = \"0\";\r\n");
      out.write("\r\n");
      out.write("		            // 3. 서버에서 새 카테고리 페이지 몰래 가져오기 (AJAX)\r\n");
      out.write("		            fetch(url)\r\n");
      out.write("		            .then(res => res.text())\r\n");
      out.write("		            .then(html => {\r\n");
      out.write("		                // 가져온 새 페이지에서 '.content-area' 안쪽 알맹이만 쏙 빼오기\r\n");
      out.write("		                const parser = new DOMParser();\r\n");
      out.write("		                const doc = parser.parseFromString(html, \"text/html\");\r\n");
      out.write("		                const newContent = doc.querySelector('.content-area').innerHTML;\r\n");
      out.write("\r\n");
      out.write("		                // 0.2초 기다렸다가 알맹이 교체 후 다시 선명하게 만들기 (Fade-in)\r\n");
      out.write("		                setTimeout(() => {\r\n");
      out.write("		                    contentArea.innerHTML = newContent;\r\n");
      out.write("		                    contentArea.style.opacity = \"1\";\r\n");
      out.write("		                    // 브라우저 주소창 URL도 자연스럽게 업데이트 (뒤로가기 지원)\r\n");
      out.write("		                    window.history.pushState(null, '', url); \r\n");
      out.write("		                }, 200);\r\n");
      out.write("		            })\r\n");
      out.write("		            .catch(err => {\r\n");
      out.write("		                window.location.href = url; // 혹시나 에러 나면 기존 방식대로 이동\r\n");
      out.write("		            });\r\n");
      out.write("		        });\r\n");
      out.write("		    });\r\n");
      out.write("		});\r\n");
      out.write("</script>\r\n");
